if (key) {
	struct key_user *user;
	unsigned int quotalen;
	bool in_quota;

	key_check(key);

	/*
	 * We must cache the values required for quota cleanup before
	 * decrementing the usage count and making the key vulnerable to
	 * the GC, which could free the key immediately.
	 */
	user = key->user;
	quotalen = key->quotalen;
	in_quota = test_bit(KEY_FLAG_IN_QUOTA, &key->flags);

	/* Pin user so it doesn't disappear if key is freed */
	refcount_inc(&user->usage);

	if (refcount_dec_and_test(&key->usage)) {
		unsigned long flags;

		/* deal with the user's key tracking and quota */
		if (in_quota) {
			spin_lock_irqsave(&user->lock, flags);
			user->qnkeys--;
			user->qnbytes -= quotalen;
			spin_unlock_irqrestore(&user->lock, flags);
		}
		schedule_work(&key_gc_work);
	}

	key_user_put(user);
}

